from fractions import Fraction as F
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
ids='TUVW'; modes='ABCD'
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
cost=list(map(F,['1.8','1.5','1.2','0.8']))
def stop(s):
 w=sum(rows[i][1] for i in s)
 return min((sum(F(rows[i][1]*loss[a][modes.index(rows[i][0])],w) for i in s),modes[a]) for a in range(4))
def testval(s,t,remaining):
 w=sum(rows[i][1] for i in s)
 v=cost[t]; policy={}
 for b in (0,1):
  sub=tuple(i for i in s if rows[i][2][t]==b)
  if not sub: policy[str(b)]='IMPOSSIBLE';continue
  val,action=best(sub,remaining)
  v+=F(sum(rows[i][1] for i in sub),w)*val
  policy[str(b)]=action
 return v,policy
def best(s,available):
 opts=[stop(s)]
 for t in available:
  v,_=testval(s,t,())
  opts.append((v,ids[t]))
 return min(opts)
s=tuple(range(8))
results={'STOP':stop(s)[0]};policies={}
for t in range(4):
 results[ids[t]],policies[ids[t]]=testval(s,t,tuple(j for j in range(4) if j!=t))
print({k:float(v) for k,v in results.items()})
print(policies)
print('stop',stop(s))
print('best',min(results,key=results.get))

